  const dec=(i,k,fr,wx)=>o.gable?{sh:o.bare&&fr&&o.bare(wx-x,i)?null:o.roof,ns:fr&&i===0&&o.door&&Math.abs(wx-o.door.x)<2.6?f*Math.sign(o.door.x-wx):0,fb:fr&&i===0?k:null}:{top:trim,fb:fr&&o.boxes&&i>0&&(k+i)%2===0?k+i:null};
